15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	            expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" "
25	                    + "+ owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
26	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
27	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
28	    @Mapping(target = "locality", expression = "java(locality(owner))")
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    /**
32	     * Fixed city-to-region table backing the owner's {@code locality}: Sydney maps to {@code 'NSW'},
33	     * Melbourne to {@code 'VIC'} and Brisbane to {@code 'QLD'}.
34	     */
35	    java.util.Map<String, String> CITY_REGIONS = java.util.Map.of(
36	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
37	
38	    /**
39	     * Derives the owner's locality (region) from city using the fixed {@link #CITY_REGIONS} table,
40	     * returning the canonical region string or {@code 'UNKNOWN'} when the city is not in the table.
41	     */
42	    default String locality(Owner owner) {
43	        return CITY_REGIONS.getOrDefault(owner.getCity(), "UNKNOWN");
44	    }
45	
46	    /**
47	     * Derives the owner's membership tier: {@code 'SILVER'} when namesakeCount is 0 and an email is
48	     * present, otherwise {@code 'BRONZE'}.
49	     */
50	    default org.springframework.samples.petclinic.rest.dto.OwnerDto.MembershipTierEnum membershipTier(Owner owner) {
51	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
52	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
53	        return noNamesakes && hasEmail
54	                ? org.springframework.samples.petclinic.rest.dto.OwnerDto.MembershipTierEnum.SILVER
55	                : org.springframework.samples.petclinic.rest.dto.OwnerDto.MembershipTierEnum.BRONZE;
56	    }
57	
58	    /**
59	     * Derives the owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
60	     * last two digits of the registrationDate year (e.g. {@code 'SYD-SMI-0007-M26'}). Returns {@code null}
61	     * when either source field is absent, so owners without a customerCode or registrationDate map cleanly.
62	     */
63	    default String membershipNumber(Owner owner) {
64	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
65	            return null;
66	        }
67	        return owner.getCustomerCode() + "-M"
68	                + String.format("%02d", owner.getRegistrationDate().getYear() % 100);
69	    }
