10	/**
11	 * Assigns the owner's {@code householdId}: a stable identifier shared by all owners who live in the
12	 * same household, i.e. share a last name and address. It is the first 12 upper-cased hex characters
13	 * of the SHA-256 of {@code '<lastName>|<address>'}, with the last name normalized exactly as
14	 * {@link CheckHouseholdUnique} normalizes it (lower-cased, runs of whitespace collapsed, trimmed) and
15	 * the address normalized to its canonical form (see {@link AddressNormalizer}).
16	 *
17	 * <p>Because the id derives only from that normalized pair, two owners who intentionally share a
18	 * household (accepted via {@code sharesHousehold}) deterministically receive the same value without
19	 * any lookup. Runs after {@link BuildOwner} has mapped the request onto the entity and before
20	 * {@link SaveOwner}, so the assigned id is persisted and returned.
21	 */
22	public class AssignHouseholdId {
23	
24	    public void service(@Val Owner owner) {
25	        String key = normalize(owner.getLastName()) + "|" + AddressNormalizer.normalize(owner.getAddress());
26	        owner.setHouseholdId(shaHex(key, 12));
27	    }
28	
29	    /** Lower-cases and collapses runs of whitespace to a single space, trimmed. */
30	    private static String normalize(String value) {
31	        if (value == null) {
32	            return "";
33	        }
34	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
35	    }
36	
37	    /** First {@code n} upper-case hex characters of SHA-256 of {@code value}. */
38	    private static String shaHex(String value, int n) {
39	        try {
40	            byte[] digest = MessageDigest.getInstance("SHA-256")
41	                    .digest(value.getBytes(StandardCharsets.UTF_8));
42	            StringBuilder sb = new StringBuilder(digest.length * 2);
43	            for (byte b : digest) {
44	                sb.append(String.format("%02X", b));
45	            }
46	            return sb.substring(0, n);
47	        }
48	        catch (NoSuchAlgorithmException e) {
49	            throw new IllegalStateException("SHA-256 not available", e);
50	        }
51	    }
52	}
